der-radius:50%;transform:rotateX(70deg);box-shadow:0 0 12px #65a6ff}.ring-b{inset:9px;border-color:rgba(106,167,255,.5);transform:rotateY(64deg) rotateX(68deg)}.art-wordmark{position:absolute;left:30px;bottom:26px;font-size:16px;letter-spacing:.2em;color:#e5efff}.art-wordmark span{font:9px var(--mono);vertical-align:top}.art-caption{position:absolute;right:28px;bottom:30px;color:#a3b8d7}.art-spark{position:absolute;color:#d1e5ff}.spark-a{top:12px;right:5px;font-size:21px}.spark-b{bottom:17px;left:0}.art-form{background:radial-gradient(ellipse at 51% 58%,#d1b48b,#927d68 37%,#514b45 100%);color:#322a24}.form-sun{position:absolute;width:110px;height:110px;border-radius:50%;background:#e2c99e;left:50%;top:30px;transform:translateX(-50%);box-shadow:0 0 75px rgba(255,223,174,.55)}.form-arch{position:absolute;width:155px;height:195px;left:50%;bottom:-27px;transform:translateX(-50%);border-radius:90px 90px 0 0;background:linear-gradient(90deg,#4c3f35,#a18b70 46%,#443a31);padding:11px 11px 0;box-shadow:12px 0 30px rgba(30,22,17,.26)}.arch-inner{height:100%;border-radius:80px 80px 0 0;background:linear-gradient(90deg,#bcaa8f,#e1d1b2 43%,#897a67)}.arch-object{position:absolute;width:74px;height:91px;left:40px;bottom:0;background:linear-gradient(100deg,#625344,#dfcba8 53%,#766752);border-radius:45px 45px 0 0}.form-title{position:absolute;left:25px;top:25px;font-size:27px;line-height:.86;letter-spacing:-.06em;font-weight:800}.form-title i{font-family:var(--serif);font-weight:400}.form-caption{position:absolute;left:25px;bottom:19px;color:rgba(52,42,33,.75);font-size:7px}.art-night{background:radial-gradient(ellipse at 50% 54%,#162b40,#09101a 76%);color:#deecf6}.night-moon{position:absolute;width:98px;height:98px;right:12%;top:38px;border-radius:50%;background:linear-gradient(135deg,#d9e3dd,#88a3a6 70%);opacity:.84;box-shadow:0 0 50px rgba(181,216,225,.16)}.night-title{position:absolute;left:27px;top:28px;font-size:39px;font-weight:600;line-height:.8;letter-spacing:-.09em}.night-