const r=await fetch('http://127.0.0.1:9223/json');
if(!r.ok) throw Error(`Chrome debug endpoint: ${r.status}`);
const targets=await r.json(); const target=targets.find(t=>t.type==='page'); if(!target)throw Error('No Chrome page target');
const ws=new WebSocket(target.webSocketDebuggerUrl); await new Promise((ok,fail)=>{ws.onopen=ok;ws.onerror=fail});
let id=0; const pending=new Map(), errors=[];
ws.onmessage=e=>{const m=JSON.parse(e.data);if(m.method==='Runtime.exceptionThrown')errors.push(m.params.exceptionDetails.text);if(m.id&&pending.has(m.id)){const p=pending.get(m.id);pending.delete(m.id);m.error?p.reject(Error(m.error.message)):p.resolve(m.result)}};
const send=(method,params={})=>{const n=++id;ws.send(JSON.stringify({id:n,method,params}));return new Promise((resolve,reject)=>pending.set(n,{resolve,reject}))};
const evaluate=async expression=>{const x=await send('Runtime.evaluate',{expression,returnByValue:true,awaitPromise:true});if(x.exceptionDetails)throw Error(x.exceptionDetails.text);return x.result.value};
await send('Page.enable');await send('Runtime.enable');await send('Page.navigate',{url:'http://localhost:3002/'});await new Promise(r=>setTimeout(r,3500));
const portfolio=await evaluate(`({title:document.title,projectLabels:[...document.querySelectorAll('.project-type')].map(e=>e.textContent),sectionLabel:document.querySelector('.section-index').textContent,projectCount:document.querySelectorAll('.project-card').length})`);
const projectDetails=[];
for(let i=0;i<3;i++){await evaluate(`document.querySelectorAll('.project-card')[${i}].click()`);projectDetails.push(await evaluate(`({title:document.querySelector('#modal-title').textContent,description:document.querySelector('.modal-description').textContent,details:[...document.querySelectorAll('.modal-details li')].map(li=>li.textContent)})`));await evaluate(`document.querySelector('.modal-close').click()`)}
await send('Page.navigate',{url:'http://localhost:3002/resume.html'});await new Promise(r=>setTimeout(r,800));const resume=await evaluate(`({title:document.title,historyNotice:document.querySelector('#experience .draft-note').textContent,conceptNotice:document.querySelectorAll('.draft-note')[1].textContent,layout:getComputedStyle(document.querySelector('.grid')).gridTemplateColumns,docWidth:document.documentElement.scrollWidth,viewport:innerWidth})`);
await send('Emulation.setDeviceMetricsOverride',{width:390,height:844,deviceScaleFactor:1,mobile:true});const mobile=await evaluate(`({width:innerWidth,docWidth:document.documentElement.scrollWidth})`);
console.log(JSON.stringify({portfolio,projectDetails,resume,mobile,browserExceptions:errors},null,2));ws.close();
